def get_neighbors(input_grid, r, c, h, w):
    """Get all neighbor coordinates"""
    needs = {}
    # Immediate vertical
    needs['up'] = (r-1, c) if r > 0 and 0 <= c < w else None
    needs['down'] = (r+1, c) if r < h-1 and 0 <= c < w else None
    # Immediate horizontal
    needs['left'] = (r, c-1) if r >= 0 and c > 0 else None  
    needs['right'] = (r, c+1) if r >= 0 and c < w-1 else None
    # Anti-diagonal (top-right + bottom-left)
    needs['anti1'] = (r-1, c+1) if r > 0 and c < w-1 else None
    needs['anti2'] = (r+1, c-1) if r < h-1 and c > 0 else None
    # Anti-diagonal (top-left + bottom-right)
    needs['anti3'] = (r-1, c-1) if r > 0 and c > 0 else None
    needs['anti4'] = (r+1, c+1) if r < h-1 and c < w-1 else None
    return needs

